 ctx.fillStyle=base; ctx.fillRect(x,y,w,h);
 ctx.fillStyle=br;
 for(let yy=y;yy<y+h;yy+=11){
  let off=(Math.floor((yy-y)/11)%2)*6;
  for(let xx=x+off;xx<x+w;xx+=11){
   if(xx+8>x+w) continue;
   ctx.fillRect(xx+1,yy+1,7,6);
  }
 }
}
